import java.util.ArrayList;
import java.util.List;

public class Solution {
    static class Trie {
        private static class Node {
            Node[] filhos = new Node[26];
            boolean fim;
        }
        private final Node raiz = new Node();

        void insert(String word) {
            var atual = raiz;
            for (char c : word.toCharArray()) {
                int i = c - 'a';
                if (atual.filhos[i] == null) atual.filhos[i] = new Node();
                atual = atual.filhos[i];
            }
            atual.fim = true;
        }

        boolean search(String word) {
            var n = descer(word);
            return n != null && n.fim;
        }

        boolean startsWith(String prefix) {
            return descer(prefix) != null;
        }

        List<String> suggest(String prefix, int limit) {
            var resultado = new ArrayList<String>();
            if (limit <= 0) return resultado;
            var n = descer(prefix);
            if (n == null) return resultado;
            coletar(n, new StringBuilder(prefix), resultado, limit);
            return resultado;
        }

        private Node descer(String s) {
            var atual = raiz;
            for (char c : s.toCharArray()) {
                int i = c - 'a';
                if (i < 0 || i >= 26 || atual.filhos[i] == null) return null;
                atual = atual.filhos[i];
            }
            return atual;
        }

        private void coletar(Node n, StringBuilder sb, List<String> out, int limit) {
            if (out.size() >= limit) return;
            if (n.fim) out.add(sb.toString());
            for (int i = 0; i < 26 && out.size() < limit; i++) {
                if (n.filhos[i] != null) {
                    sb.append((char) ('a' + i));
                    coletar(n.filhos[i], sb, out, limit);
                    sb.deleteCharAt(sb.length() - 1);
                }
            }
        }
    }
}

