import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class SolutionTest {
    @Test void buscaEPrefixo() {
        var t = new Solution.Trie();
        t.insert("casa");
        assertTrue(t.search("casa"));
        assertFalse(t.search("cas"));
        assertTrue(t.startsWith("cas"));
    }

    @Test void sugestoesOrdenadas() {
        var t = new Solution.Trie();
        t.insert("casa"); t.insert("carro"); t.insert("cama");
        assertEquals(java.util.List.of("cama", "carro"), t.suggest("ca", 2));
    }

    @Test void prefixoInexistente() {
        var t = new Solution.Trie();
        t.insert("java");
        assertTrue(t.suggest("py", 3).isEmpty());
        assertTrue(t.suggest("ja", 0).isEmpty());
    }
}
